async function retry(fn, attempts = 3, delay = 500) {
  for (let i = 0; i < attempts; i++) {
    try { return await fn(); }
    catch (err) { if (i === attempts - 1) throw err; await new Promise(r => setTimeout(r, delay * 2 ** i)); }
  }
}

